 91→  const displayItems = useMemo(() => condenseMessages(messages), [messages]);
 92→  const isActive = status === "connected" || status === "thinking";
 93→  const isArchived = status === "done" || status === "disconnected" || status === "error";
 94→
 95→  function handleSubmit(e: React.FormEvent) {
 96→    e.preventDefault();
 97→    const trimmed = input.trim();
 98→    if (!trimmed) return;
 99→
100→    if (isActive) {
101→      onSendMessage(trimmed);
102→    } else {
103→      onSpawnAgent(trimmed);
104→    }
105→    setInput("");
106→    setShowSlashMenu(false);
107→  }
108→
109→  function handleInputChange(e: React.ChangeEvent<HTMLInputElement>) {
110→    const value = e.target.value;
111→    setInput(value);
112→
113→    if (value.startsWith("/")) {
114→      setShowSlashMenu(true);
115→      setSlashQuery(value.slice(1));
116→      setSlashHighlight(0);
117→    } else {
118→      setShowSlashMenu(false);
119→      setSlashQuery("");
120→    }
121→  }
122→
123→  function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
124→    if (!showSlashMenu) return;
125→    const filtered = filterCommands(slashQuery);
126→    if (filtered.length === 0) return;
127→
128→    if (e.key === "ArrowDown") {
129→      e.preventDefault();
130→      setSlashHighlight((i) => (i + 1) % filtered.length);
131→    } else if (e.key === "ArrowUp") {
132→      e.preventDefault();
133→      setSlashHighlight((i) => (i - 1 + filtered.length) % filtered.length);
134→    } else if (e.key === "Enter") {
135→      e.preventDefault();
136→      handleCommandSelect(filtered[slashHighlight]);
137→    } else if (e.key === "Escape") {
138→      e.preventDefault();
139→      setShowSlashMenu(false);
140→    } else if (e.key === "Tab") {
141→      e.preventDefault();
142→      setInput(`/${filtered[slashHighlight].name} `);
143→      setShowSlashMenu(false);
144→    }
145→  }
146→
147→  function handleCommandSelect(command: SlashCommand) {
148→    setShowSlashMenu(false);
149→    setSlashQuery("");
150→    setInput("");
151→
152→    if (command.clientSide) {
153→      if (command.name === "clear") {
154→        onClearHistory?.();
155→      } else if (command.name === "context") {
156→        setShowContext((v) => !v);
157→      }
158→      return;
159→    }
160→
161→    const commandText = `/${command.name}`;
162→    if (isActive) {
163→      onSendMessage(commandText);
