 70→export function ControlRequest({
 71→  message,
 72→  onRespond,
 73→}: {
 74→  message: ChatMessage;
 75→  onRespond: (requestId: string, allow: boolean) => void;
 76→}) {
 77→  const cr = message.controlRequest;
 78→  if (!cr) return null;
 79→
 80→  const { display, namespace } = formatToolName(cr.tool_name);
 81→
 82→  return (
 83→    <div
 84→      className={`mx-auto w-full max-w-2xl rounded-lg border-2 border-dashed border-muted-foreground/30 p-3 md:p-4 ${
 85→        cr.resolved ? "opacity-60" : ""
 86→      }`}
 87→    >
 88→      {/* Header */}
 89→      <div className="mb-3 flex items-center gap-2">
 90→        <ShieldAlert className="h-4 w-4 shrink-0 text-yellow-500" />
 91→        <span className="text-sm font-semibold">{display}</span>
 92→        {namespace && (
 93→          <span className="text-xs text-muted-foreground">{namespace}</span>
 94→        )}
 95→      </div>
 96→
 97→      {/* Description */}
 98→      {cr.description && (
 99→        <p className="mb-3 text-xs text-muted-foreground">{cr.description}</p>
100→      )}
101→
102→      {/* Input parameters */}
103→      <div className="mb-3 space-y-2">
104→        {Object.entries(cr.input).map(([key, value]) => (
105→          <InputField key={key} name={key} value={value} />
106→        ))}
107→      </div>
108→
109→      {/* Actions / Resolved state */}
110→      {!cr.resolved ? (
111→        <div className="flex gap-2">
112→          <Button size="sm" onClick={() => onRespond(cr.id, true)}>
113→            <Check className="mr-1 h-3 w-3" />
114→            Allow
115→          </Button>
116→          <Button
117→            size="sm"
118→            variant="outline"
119→            onClick={() => onRespond(cr.id, false)}
120→          >
121→            <X className="mr-1 h-3 w-3" />
122→            Deny
123→          </Button>
124→        </div>
125→      ) : (
126→        <span
127→          className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium ${
128→            cr.allowed
129→              ? "bg-green-500/15 text-green-400"
130→              : "bg-red-500/15 text-red-400"
131→          }`}
132→        >
133→          {cr.allowed ? "Allowed" : "Denied"}
134→        </span>
135→      )}
136→    </div>
137→  );
138→}
