 14→import { cn } from "@/lib/utils";
 15→
 16→/** Per-question selection state. */
 17→interface QuestionState {
 18→  selected: Set<number>;
 19→  otherActive: boolean;
 20→  otherText: string;
 21→}
 22→
 23→export function UserQuestion({
 24→  message,
 25→  onRespond,
 26→}: {
 27→  message: ChatMessage;
 28→  onRespond: (requestId: string, answers: Record<string, string>) => void;
 29→}) {
 30→  const uq = message.userQuestion;
 31→  if (!uq) return null;
 32→
 33→  const questions = uq.questions;
 34→
 35→  const [states, setStates] = useState<QuestionState[]>(() =>
 36→    questions.map(() => ({ selected: new Set<number>(), otherActive: false, otherText: "" }))
 37→  );
 38→
 39→  function updateQuestion(qIdx: number, updater: (prev: QuestionState) => QuestionState) {
 40→    if (uq.resolved) return;
 41→    setStates((prev) => prev.map((s, i) => (i === qIdx ? updater(s) : s)));
 42→  }
 43→
 44→  function toggleOption(qIdx: number, optIdx: number, multiSelect: boolean) {
 45→    updateQuestion(qIdx, (prev) => {
 46→      const sel = new Set(prev.selected);
 47→      if (multiSelect) {
 48→        if (sel.has(optIdx)) sel.delete(optIdx);
 49→        else sel.add(optIdx);
 50→      } else {
 51→        if (sel.has(optIdx)) sel.clear();
 52→        else {
 53→          sel.clear();
 54→          sel.add(optIdx);
 55→        }
 56→        // Single-select: picking a predefined option deactivates "Other"
 57→        return { ...prev, selected: sel, otherActive: false, otherText: "" };
 58→      }
 59→      return { ...prev, selected: sel };
 60→    });
 61→  }
 62→
 63→  function toggleOther(qIdx: number, multiSelect: boolean) {
 64→    updateQuestion(qIdx, (prev) => {
 65→      if (prev.otherActive) {
 66→        // Deactivate
 67→        return { ...prev, otherActive: false, otherText: "" };
 68→      }
 69→      // Activate — for single-select, clear predefined selections
 70→      return {
 71→        selected: multiSelect ? prev.selected : new Set<number>(),
 72→        otherActive: true,
 73→        otherText: prev.otherText,
 74→      };
 75→    });
 76→  }
 77→
 78→  function setOtherText(qIdx: number, text: string) {
 79→    updateQuestion(qIdx, (prev) => ({ ...prev, otherText: text }));
 80→  }
 81→
 82→  function handleSubmit() {
 83→    const answers: Record<string, string> = {};
 84→    questions.forEach((q, i) => {
 85→      const st = states[i];
 86→      const labels = q.options
 87→        .filter((_, j) => st.selected.has(j))
 88→        .map((o) => o.label);
 89→      if (st.otherActive && st.otherText.trim()) {
 90→        labels.push(st.otherText.trim());
 91→      }
 92→      answers[`q${i}`] = labels.join(", ");
 93→    });
 94→    onRespond(uq.requestId, answers);
 95→  }
 96→
 97→  // Every question must have at least one selection or non-empty "Other" text
 98→  const allAnswered = questions.every((_, i) => {
 99→    const st = states[i];
100→    if (st.selected.size > 0) return true;
101→    if (st.otherActive && st.otherText.trim()) return true;
102→    return false;
103→  });
104→
105→  return (
106→    <div className="mx-auto w-full max-w-lg space-y-4 rounded-lg border-2 border-dashed border-muted-foreground/30 p-3 md:p-4">
107→      {questions.map((q, i) => (
108→        <QuestionBlock
109→          key={i}
110→          question={q.question}
111→          header={q.header}
112→          options={q.options}
113→          multiSelect={q.multiSelect}
114→          resolved={uq.resolved}
115→          state={states[i]}
116→          onToggleOption={(optIdx) => toggleOption(i, optIdx, q.multiSelect)}
117→          onToggleOther={() => toggleOther(i, q.multiSelect)}
118→          onOtherTextChange={(text) => setOtherText(i, text)}
119→        />
120→      ))}
121→      {!uq.resolved ? (
122→        <Button size="sm" disabled={!allAnswered} onClick={handleSubmit}>
123→          Submit
124→        </Button>
125→      ) : (
126→        <div className="text-xs italic text-muted-foreground">Answered</div>
127→      )}
128→    </div>
129→  );
130→}
131→
132→function QuestionBlock({
133→  question,
134→  header,
135→  options,
136→  resolved,
137→  state,
138→  onToggleOption,
139→  onToggleOther,
140→  onOtherTextChange,
141→}: {
142→  question: string;
143→  header?: string;
144→  options: { label: string; description?: string }[];
145→  multiSelect: boolean;
146→  resolved?: boolean;
147→  state: QuestionState;
148→  onToggleOption: (optIdx: number) => void;
149→  onToggleOther: () => void;
150→  onOtherTextChange: (text: string) => void;
151→}) {
152→  const inputRef = useRef<HTMLInputElement>(null);
153→
154→  return (
155→    <div>
156→      {header && (
157→        <div className="mb-1 text-xs font-semibold text-muted-foreground">
158→          {header}
159→        </div>
160→      )}
161→      <div className="mb-3 text-sm">{question}</div>
162→      <div className="flex flex-wrap gap-2">
163→        {options.map((opt, i) => (
164→          <button
165→            key={i}
166→            type="button"
167→            disabled={!!resolved}
168→            onClick={() => onToggleOption(i)}
169→            className={cn(
170→              "rounded-md border px-3 py-1.5 text-xs transition-colors",
171→              state.selected.has(i)
172→                ? "border-primary bg-primary text-primary-foreground"
173→                : "border-muted-foreground/30 bg-secondary hover:border-primary/50",
174→              resolved && "opacity-60 cursor-default"
175→            )}
176→            title={opt.description}
177→          >
178→            {opt.label}
179→            {opt.description && (
180→              <span className="ml-1 text-[10px] opacity-70">
181→                — {opt.description}
182→              </span>
183→            )}
184→          </button>
185→        ))}
186→        <button
187→          type="button"
188→          disabled={!!resolved}
189→          onClick={() => {
190→            onToggleOther();
191→            // Focus the input after React re-renders
192→            setTimeout(() => inputRef.current?.focus(), 0);
193→          }}
194→          className={cn(
195→            "rounded-md border px-3 py-1.5 text-xs transition-colors",
196→            state.otherActive
197→              ? "border-primary bg-primary text-primary-foreground"
198→              : "border-muted-foreground/30 bg-secondary hover:border-primary/50",
199→            resolved && "opacity-60 cursor-default"
200→          )}
201→        >
202→          Other
203→          <span className="ml-1 text-[10px] opacity-70">
204→            — Provide your own response
205→          </span>
206→        </button>
207→      </div>
208→      {state.otherActive && !resolved && (
209→        <input
210→          ref={inputRef}
211→          type="text"
212→          value={state.otherText}
213→          onChange={(e) => onOtherTextChange(e.target.value)}
214→          placeholder="Tell Claude what to do instead..."
215→          className="mt-2 w-full rounded-md border border-muted-foreground/30 bg-secondary px-3 py-1.5 text-xs outline-none focus:border-primary"
216→        />
217→      )}
218→    </div>
219→  );
220→}
