  3→import { useMemo, useState } from "react";
  4→import { ChevronDown, ChevronRight, Clock, Cpu, DollarSign, FileText, RotateCw, Zap } from "lucide-react";
  5→import type { ClaudeMessage, ClaudeResult, ClaudeSystemInit } from "@/lib/types";
  6→import { cn } from "@/lib/utils";
  7→
  8→// ── Types ────────────────────────────────────────────────────────────────
  9→
 10→interface ResultUsage {
 11→  input_tokens?: number;
 12→  output_tokens?: number;
 13→  cache_read_input_tokens?: number;
 14→  cache_creation_input_tokens?: number;
 15→}
 16→
 17→interface ContextStats {
 18→  model: string;
 19→  cwd: string;
 20→  totalCost: number;
 21→  totalDurationMs: number;
 22→  totalTurns: number;
 23→  inputTokens: number;
 24→  outputTokens: number;
 25→  cacheReadTokens: number;
 26→  cacheCreationTokens: number;
 27→  totalMessages: number;
 28→  toolUseCount: number;
 29→}
 30→
 31→// ── Stats computation ────────────────────────────────────────────────────
 32→
 33→function computeContextStats(rawMessages: ClaudeMessage[], activeModel?: string | null): ContextStats {
 34→  let model = activeModel ?? "";
 35→  let cwd = "";
 36→  let totalCost = 0;
 37→  let totalDurationMs = 0;
 38→  let totalTurns = 0;
 39→  let inputTokens = 0;
 40→  let outputTokens = 0;
 41→  let cacheReadTokens = 0;
 42→  let cacheCreationTokens = 0;
 43→  let toolUseCount = 0;
 44→
 45→  for (const msg of rawMessages) {
 46→    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
 47→      const init = msg as ClaudeSystemInit;
 48→      if (!model) model = init.model;
 49→      cwd = init.cwd;
 50→    }
 51→
 52→    if (msg.type === "result") {
 53→      const result = msg as ClaudeResult & { usage?: ResultUsage };
 54→      totalCost = result.total_cost_usd ?? result.cost_usd ?? totalCost;
 55→      totalDurationMs += result.duration_ms ?? 0;
 56→      totalTurns += result.num_turns ?? 0;
 57→      const u = result.usage;
 58→      if (u) {
 59→        inputTokens += u.input_tokens ?? 0;
 60→        outputTokens += u.output_tokens ?? 0;
 61→        cacheReadTokens += u.cache_read_input_tokens ?? 0;
 62→        cacheCreationTokens += u.cache_creation_input_tokens ?? 0;
 63→      }
 64→    }
 65→
 66→    if (msg.type === "assistant") {
 67→      const content = (msg as { message?: { content?: { type: string; name?: string }[] } }).message?.content;
 68→      if (Array.isArray(content)) {
 69→        toolUseCount += content.filter((b) => b.type === "tool_use").length;
 70→      }
 71→    }
 72→  }
 73→
 74→  return {
 75→    model,
 76→    cwd,
 77→    totalCost,
 78→    totalDurationMs,
 79→    totalTurns,
 80→    inputTokens,
 81→    outputTokens,
 82→    cacheReadTokens,
 83→    cacheCreationTokens,
 84→    totalMessages: rawMessages.length,
 85→    toolUseCount,
 86→  };
 87→}
 88→
 89→// ── Formatting helpers ───────────────────────────────────────────────────
 90→
 91→function formatTokens(n: number): string {
 92→  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
 93→  if (n >= 1_000) return `${(n / 1_000).toFixed(1)}k`;
 94→  return `${n}`;
 95→}
 96→
 97→function formatCost(usd: number): string {
 98→  if (usd < 0.01) return `$${usd.toFixed(4)}`;
 99→  return `$${usd.toFixed(2)}`;
100→}
101→
102→function formatDuration(ms: number): string {
103→  if (ms < 1000) return `${ms}ms`;
104→  const seconds = ms / 1000;
105→  if (seconds < 60) return `${seconds.toFixed(1)}s`;
106→  const minutes = Math.floor(seconds / 60);
107→  const remainingSeconds = Math.round(seconds % 60);
108→  return `${minutes}m ${remainingSeconds}s`;
109→}
110→
111→// ── Token breakdown bar colors ───────────────────────────────────────────
112→
113→const TOKEN_CATEGORIES = [
114→  { key: "input", label: "Input tokens", color: "bg-blue-400" },
115→  { key: "output", label: "Output tokens", color: "bg-green-400" },
116→  { key: "cacheRead", label: "Cache read", color: "bg-purple-400" },
117→  { key: "cacheCreation", label: "Cache write", color: "bg-orange-400" },
118→] as const;
119→
120→// ── Collapsible section ──────────────────────────────────────────────────
121→
122→function CollapsibleSection({
123→  title,
124→  icon: Icon,
125→  defaultOpen,
126→  children,
127→}: {
128→  title: string;
129→  icon: typeof FileText;
130→  defaultOpen?: boolean;
131→  children: React.ReactNode;
132→}) {
133→  const [open, setOpen] = useState(defaultOpen ?? false);
134→
135→  return (
136→    <div>
137→      <button
138→        onClick={() => setOpen((v) => !v)}
139→        className="flex w-full items-center gap-1.5 text-xs text-muted-foreground hover:text-foreground transition-colors"
140→      >
141→        {open ? <ChevronDown className="size-3" /> : <ChevronRight className="size-3" />}
142→        <Icon className="size-3" />
143→        <span>{title}</span>
144→      </button>
145→      {open && <div className="mt-1.5 space-y-1 pl-5">{children}</div>}
146→    </div>
147→  );
148→}
