150→// ── Main component ───────────────────────────────────────────────────────
151→
152→export function ContextUsageCard({
153→  rawMessages,
154→  activeModel,
155→}: {
156→  rawMessages: ClaudeMessage[];
157→  activeModel?: string | null;
158→}) {
159→  const stats = useMemo(() => computeContextStats(rawMessages, activeModel), [rawMessages, activeModel]);
160→
161→  const totalTokens = stats.inputTokens + stats.outputTokens + stats.cacheReadTokens + stats.cacheCreationTokens;
162→
163→  const tokenBreakdown = [
164→    { ...TOKEN_CATEGORIES[0], value: stats.inputTokens },
165→    { ...TOKEN_CATEGORIES[1], value: stats.outputTokens },
166→    { ...TOKEN_CATEGORIES[2], value: stats.cacheReadTokens },
167→    { ...TOKEN_CATEGORIES[3], value: stats.cacheCreationTokens },
168→  ].filter((t) => t.value > 0);
169→
170→  return (
171→    <div className="max-w-[90%] md:max-w-[80%] rounded-lg border bg-card px-4 py-3 space-y-3">
