173→      <div className="flex items-center justify-between gap-3">
174→        <div className="flex items-center gap-2">
175→          <Cpu className="size-4 text-muted-foreground" />
176→          <span className="text-sm font-medium">Context Usage</span>
177→        </div>
178→        {stats.model && (
