180→            {stats.model}
181→          </span>
182→        )}
183→      </div>
184→
185→      {/* Token summary */}
186→      {totalTokens > 0 && (
187→        <div className="space-y-1.5">
188→          <div className="flex items-baseline justify-between">
189→            <span className="text-2xl font-semibold tabular-nums">{formatTokens(totalTokens)}</span>
190→            <span className="text-xs text-muted-foreground">total tokens used</span>
191→          </div>
192→
193→          {/* Stacked bar */}
194→          {tokenBreakdown.length > 0 && (
195→            <div className="flex h-3 w-full overflow-hidden rounded-full bg-secondary">
196→              {tokenBreakdown.map((cat) => (
197→                <div
198→                  key={cat.key}
199→                  className={cn("h-full first:rounded-l-full last:rounded-r-full", cat.color)}
200→                  style={{ width: `${(cat.value / totalTokens) * 100}%` }}
201→                  title={`${cat.label}: ${formatTokens(cat.value)}`}
202→                />
203→              ))}
204→            </div>
205→          )}
206→
207→          {/* Token breakdown legend */}
208→          <div className="space-y-1">
209→            {tokenBreakdown.map((cat) => (
210→              <div key={cat.key} className="flex items-center gap-2 text-xs">
