212→                <span className="flex-1 text-muted-foreground">{cat.label}</span>
213→                <span className="tabular-nums text-foreground/80">{formatTokens(cat.value)}</span>
214→                <span className="w-12 text-right tabular-nums text-muted-foreground/60">
215→                  {((cat.value / totalTokens) * 100).toFixed(1)}%
