226→          <DollarSign className="size-3.5 text-muted-foreground" />
227→          <div>
228→            <div className="text-xs text-muted-foreground">Cost</div>
229→            <div className="text-sm font-medium tabular-nums">{formatCost(stats.totalCost)}</div>
230→          </div>
231→        </div>
232→        <div className="flex items-center gap-2 rounded-md bg-secondary/50 px-3 py-2">
233→          <Clock className="size-3.5 text-muted-foreground" />
234→          <div>
235→            <div className="text-xs text-muted-foreground">Duration</div>
236→            <div className="text-sm font-medium tabular-nums">{formatDuration(stats.totalDurationMs)}</div>
237→          </div>
238→        </div>
239→        <div className="flex items-center gap-2 rounded-md bg-secondary/50 px-3 py-2">
240→          <RotateCw className="size-3.5 text-muted-foreground" />
241→          <div>
242→            <div className="text-xs text-muted-foreground">Turns</div>
