245→        </div>
246→        <div className="flex items-center gap-2 rounded-md bg-secondary/50 px-3 py-2">
247→          <Zap className="size-3.5 text-muted-foreground" />
248→          <div>
249→            <div className="text-xs text-muted-foreground">Tool calls</div>
250→            <div className="text-sm font-medium tabular-nums">{stats.toolUseCount}</div>
251→          </div>
252→        </div>
253→      </div>
254→
255→      {/* Working directory */}
256→      {stats.cwd && (
257→        <CollapsibleSection title="Session info" icon={FileText}>
258→          <div className="text-[11px]">
