 32→export function Chat({
 33→  connected,
 34→  loading,
 35→  status,
 36→  agentLabel,
 37→  messages,
 38→  rawMessages,
 39→  activeModel,
 40→  selectedModel,
 41→  onModelChange,
 42→  onSendMessage,
 43→  onSpawnAgent,
 44→  onRespondToControl,
 45→  onRespondToUserQuestion,
 46→  onClearHistory,
 47→  showTasks,
 48→  onToggleTasks,
 49→  showDiffs,
 50→  onToggleDiffs,
 51→  onToggleSidebar,
 52→  onOpenSfxSettings,
 53→}: {
 54→  connected: boolean;
 55→  loading?: boolean;
 56→  status: AgentStatus;
 57→  agentLabel?: string | null;
 58→  messages: ChatMessage[];
 59→  rawMessages: ClaudeMessage[];
 60→  activeModel?: string | null;
 61→  selectedModel?: string;
 62→  onModelChange?: (model: string) => void;
 63→  onSendMessage: (content: string) => void;
 64→  onSpawnAgent: (prompt: string) => void;
 65→  onRespondToControl: (requestId: string, allow: boolean) => void;
 66→  onRespondToUserQuestion: (requestId: string, answers: Record<string, string>) => void;
 67→  onClearHistory?: () => void;
 68→  showTasks?: boolean;
 69→  onToggleTasks?: () => void;
 70→  showDiffs?: boolean;
 71→  onToggleDiffs?: () => void;
 72→  onToggleSidebar?: () => void;
 73→  onOpenSfxSettings?: () => void;
 74→}) {
 75→  const [input, setInput] = useState("");
 76→  const [showRaw, setShowRaw] = useState(false);
 77→  const [showContext, setShowContext] = useState(false);
 78→  const [showSlashMenu, setShowSlashMenu] = useState(false);
 79→  const [slashQuery, setSlashQuery] = useState("");
 80→  const [slashHighlight, setSlashHighlight] = useState(0);
 81→  const scrollRef = useRef<HTMLDivElement>(null);
 82→  const inputRef = useRef<HTMLInputElement>(null);
 83→
 84→  useEffect(() => {
 85→    scrollRef.current?.scrollTo({
 86→      top: scrollRef.current.scrollHeight,
 87→      behavior: "smooth",
 88→    });
 89→  }, [messages, rawMessages, showRaw]);
 90→
 91→  const displayItems = useMemo(() => condenseMessages(messages), [messages]);
 92→  const isActive = status === "connected" || status === "thinking";
 93→  const isArchived = status === "done" || status === "disconnected" || status === "error";
 94→
 95→  function handleSubmit(e: React.FormEvent) {
 96→    e.preventDefault();
 97→    const trimmed = input.trim();
 98→    if (!trimmed) return;
 99→
100→    if (isActive) {
101→      onSendMessage(trimmed);
102→    } else {
103→      onSpawnAgent(trimmed);
104→    }
105→    setInput("");
106→    setShowSlashMenu(false);
107→  }
108→
109→  function handleInputChange(e: React.ChangeEvent<HTMLInputElement>) {
110→    const value = e.target.value;
111→    setInput(value);
112→
113→    if (value.startsWith("/")) {
114→      setShowSlashMenu(true);
115→      setSlashQuery(value.slice(1));
116→      setSlashHighlight(0);
117→    } else {
118→      setShowSlashMenu(false);
119→      setSlashQuery("");
120→    }
121→  }
122→
123→  function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
124→    if (!showSlashMenu) return;
125→    const filtered = filterCommands(slashQuery);
126→    if (filtered.length === 0) return;
127→
128→    if (e.key === "ArrowDown") {
129→      e.preventDefault();
130→      setSlashHighlight((i) => (i + 1) % filtered.length);
131→    } else if (e.key === "ArrowUp") {
132→      e.preventDefault();
133→      setSlashHighlight((i) => (i - 1 + filtered.length) % filtered.length);
134→    } else if (e.key === "Enter") {
135→      e.preventDefault();
136→      handleCommandSelect(filtered[slashHighlight]);
137→    } else if (e.key === "Escape") {
138→      e.preventDefault();
139→      setShowSlashMenu(false);
140→    } else if (e.key === "Tab") {
141→      e.preventDefault();
142→      setInput(`/${filtered[slashHighlight].name} `);
143→      setShowSlashMenu(false);
144→    }
145→  }
146→
147→  function handleCommandSelect(command: SlashCommand) {
148→    setShowSlashMenu(false);
149→    setSlashQuery("");
150→    setInput("");
151→
152→    if (command.clientSide) {
153→      if (command.name === "clear") {
154→        onClearHistory?.();
155→      } else if (command.name === "context") {
156→        setShowContext((v) => !v);
157→      }
158→      return;
159→    }
160→
161→    const commandText = `/${command.name}`;
162→    if (isActive) {
163→      onSendMessage(commandText);
164→    } else {
165→      onSpawnAgent(commandText);
166→    }
167→  }
168→
169→  return (
170→    <div className="flex h-full flex-col">
171→      <StatusBar
172→        connected={connected}
173→        status={status}
174→        agentLabel={agentLabel}
175→        activeModel={activeModel}
176→        selectedModel={selectedModel}
177→        onModelChange={onModelChange}
178→        showRaw={showRaw}
179→        onToggleRaw={() => setShowRaw((v) => !v)}
180→        showTasks={showTasks}
181→        onToggleTasks={onToggleTasks}
182→        showDiffs={showDiffs}
183→        onToggleDiffs={onToggleDiffs}
184→        onToggleSidebar={onToggleSidebar}
185→        onOpenSfxSettings={onOpenSfxSettings}
186→      />
187→
188→      <AgentSummary rawMessages={rawMessages} />
189→
190→      <div ref={scrollRef} className="flex-1 overflow-y-auto p-2 md:p-4 space-y-2">
191→        {loading ? (
192→          <div className="flex h-full flex-col items-center justify-center gap-3">
193→            <div className="flex gap-1">
194→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse" />
195→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:150ms]" />
196→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:300ms]" />
197→            </div>
198→            <span className="text-xs text-muted-foreground">
199→              {connected ? "Loading messages..." : "Connecting..."}
200→            </span>
201→          </div>
202→        ) : showRaw ? (
203→          rawMessages.length === 0 ? (
204→            <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
205→              No raw messages yet
206→            </div>
207→          ) : (
208→            <div className="space-y-1">
209→              {rawMessages.map((msg, i) => (
210→                <RawMessage key={i} message={msg} index={i} />
211→              ))}
212→            </div>
213→          )
214→        ) : (
215→          <>
216→            {messages.length === 0 && (
217→              <div className="flex h-full flex-col items-center justify-center gap-4 text-muted-foreground">
218→                <Terminal className="size-10 opacity-30" />
219→                <div className="text-center">
220→                  <p className="text-sm font-medium text-foreground/80">No agent selected</p>
221→                  <p className="mt-1 text-xs">Type a prompt below to spawn a Claude agent</p>
222→                </div>
223→                <div className="mt-2 grid grid-cols-2 gap-3 text-[11px]">
224→                  <div className="flex items-start gap-2 rounded-lg border p-3">
225→                    <MessageSquare className="mt-0.5 size-3.5 shrink-0 text-primary" />
226→                    <div>
227→                      <p className="font-medium text-foreground/80">Chat</p>
228→                      <p className="mt-0.5">Send prompts and review tool calls in real time</p>
229→                    </div>
230→                  </div>
231→                  <div className="flex items-start gap-2 rounded-lg border p-3">
232→                    <ListTodo className="mt-0.5 size-3.5 shrink-0 text-primary" />
233→                    <div>
234→                      <p className="font-medium text-foreground/80">Tasks</p>
235→                      <p className="mt-0.5">Track work with a kanban board and delegate to agents</p>
236→                    </div>
237→                  </div>
238→                </div>
239→              </div>
240→            )}
241→            {displayItems.map((item) => {
242→              if (item.kind === "condensed") {
243→                return <CondensedToolGroup key={item.id} group={item} onSendMessage={onSendMessage} />;
244→              }
245→              const msg = item.message;
246→              return msg.userQuestion ? (
247→                <UserQuestion
248→                  key={msg.id}
249→                  message={msg}
250→                  onRespond={onRespondToUserQuestion}
251→                />
252→              ) : msg.controlRequest ? (
253→                <ControlRequest
254→                  key={msg.id}
255→                  message={msg}
256→                  onRespond={onRespondToControl}
257→                />
258→              ) : (
259→                <Message key={msg.id} message={msg} onSendMessage={onSendMessage} />
260→              );
261→            })}
262→            {showContext && (
263→              <div className="flex flex-col gap-0.5 items-start">
264→                <ContextUsageCard rawMessages={rawMessages} activeModel={activeModel} />
265→              </div>
266→            )}
267→          </>
268→        )}
269→      </div>
270→
271→      {isArchived && messages.length > 0 ? (
272→        <div className="border-t px-4 py-2 text-center text-xs text-muted-foreground">
273→          This session has ended
274→        </div>
275→      ) : (
276→        <form
277→          onSubmit={handleSubmit}
278→          className="relative flex gap-2 border-t px-2 py-2 md:px-4 md:py-3"
279→        >
280→          {showSlashMenu && (
281→            <SlashCommandMenu
282→              query={slashQuery}
283→              highlightedIndex={slashHighlight}
284→              onSelect={handleCommandSelect}
285→              onHighlight={setSlashHighlight}
286→            />
287→          )}
288→          <input
289→            ref={inputRef}
290→            type="text"
291→            value={input}
292→            onChange={handleInputChange}
293→            onKeyDown={handleKeyDown}
294→            placeholder={isActive ? "Send a follow-up..." : "Enter a prompt to spawn agent..."}
295→            className="flex-1 rounded-md border bg-background px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-ring"
296→          />
297→          <Button type="submit" disabled={!connected || !input.trim()}>
298→            {isActive ? "Send" : "Spawn"}
299→          </Button>
300→        </form>
301→      )}
302→    </div>
303→  );
304→}
