 14→
 15→/** Format "Mcp__server__tool_name" → { display: "tool_name", namespace: "server" } */
 16→function formatToolName(raw: string): { display: string; namespace?: string } {
 17→  // MCP namespaced tools: Mcp__<server>__<tool>
 18→  const mcpMatch = raw.match(/^Mcp__([^_]+(?:__[^_]+)*)__(.+)$/);
 19→  if (mcpMatch) {
 20→    return { display: mcpMatch[2], namespace: mcpMatch[1] };
 21→  }
 22→  return { display: raw };
 23→}
 24→
 25→/** Determine if a string value is "long" (multi-line or > 80 chars). */
 26→function isLongValue(value: string): boolean {
 27→  return value.includes("\n") || value.length > 80;
 28→}
 29→
 30→function InputField({ name, value }: { name: string; value: unknown }) {
 31→  if (value === null || value === undefined) return null;
 32→
 33→  // String values: short → inline code, long → scrollable code block
 34→  if (typeof value === "string") {
 35→    return (
 36→      <div className="space-y-1">
 37→        <div className="text-xs font-medium text-muted-foreground">{name}</div>
 38→        {isLongValue(value) ? (
 39→          <pre className="max-h-48 overflow-auto rounded bg-secondary p-2 text-xs whitespace-pre-wrap break-all">
 40→            {value}
 41→          </pre>
 42→        ) : (
 43→          <code className="rounded bg-secondary px-1.5 py-0.5 text-xs">{value}</code>
 44→        )}
 45→      </div>
 46→    );
 47→  }
 48→
 49→  // Boolean / number: inline code
 50→  if (typeof value === "boolean" || typeof value === "number") {
 51→    return (
 52→      <div className="space-y-1">
 53→        <div className="text-xs font-medium text-muted-foreground">{name}</div>
 54→        <code className="rounded bg-secondary px-1.5 py-0.5 text-xs">{String(value)}</code>
 55→      </div>
 56→    );
 57→  }
 58→
 59→  // Arrays and objects: JSON code block
 60→  return (
 61→    <div className="space-y-1">
 62→      <div className="text-xs font-medium text-muted-foreground">{name}</div>
 63→      <pre className="max-h-48 overflow-auto rounded bg-secondary p-2 text-xs">
 64→        {JSON.stringify(value, null, 2)}
 65→      </pre>
 66→    </div>
 67→  );
 68→}
