 93→          <span className="text-xs text-muted-foreground">{namespace}</span>
 94→        )}
 95→      </div>
 96→
 97→      {/* Description */}
 98→      {cr.description && (
 99→        <p className="mb-3 text-xs text-muted-foreground">{cr.description}</p>
100→      )}
101→
102→      {/* Input parameters */}
103→      <div className="mb-3 space-y-2">
104→        {Object.entries(cr.input).map(([key, value]) => (
105→          <InputField key={key} name={key} value={value} />
106→        ))}
107→      </div>
108→
109→      {/* Actions / Resolved state */}
