  2→
  3→/**
  4→ * Single chat message bubble.
  5→ * - **user** — right-aligned, primary background.
  6→ * - **assistant** — left-aligned, secondary background, markdown rendered.
  7→ * - **system** — centered, italic, muted (used for init info, result summaries, errors).
  8→ *
  9→ * Includes:
 10→ * - Relative timestamps ("just now", "2m ago") with absolute time on hover.
 11→ * - Copy button on hover for user/assistant messages.
 12→ * - Markdown rendering for assistant messages via react-markdown + remark-gfm.
 13→ * - Inline diffs for assistant messages that contain file-modifying tool calls
 14→ *   (Edit, Write, MultiEdit). These are rendered automatically below the
 15→ *   message text via {@link DiffViewer}. This covers standalone messages
 16→ *   that aren't part of a condensed group — condensed groups handle diffs
 17→ *   separately in {@link CondensedToolGroup}.
 18→ */
 19→
 20→import { useEffect, useState } from "react";
 21→import { Check, Copy } from "lucide-react";
 22→import Markdown from "react-markdown";
 23→import remarkGfm from "remark-gfm";
 24→import type { ChatMessage } from "@/lib/types";
 25→import { cn } from "@/lib/utils";
 26→import { DiffViewer } from "./diff-viewer";
 27→
 28→// ── Relative time formatting ────────────────────────────────────────────
 29→
 30→function formatRelativeTime(ts: number): string {
 31→  const diff = Date.now() - ts;
 32→  if (diff < 10_000) return "just now";
 33→  if (diff < 60_000) return `${Math.floor(diff / 1000)}s ago`;
 34→  if (diff < 3_600_000) return `${Math.floor(diff / 60_000)}m ago`;
 35→  if (diff < 86_400_000) return `${Math.floor(diff / 3_600_000)}h ago`;
 36→  return `${Math.floor(diff / 86_400_000)}d ago`;
 37→}
 38→
 39→function formatAbsoluteTime(ts: number): string {
 40→  return new Date(ts).toLocaleString();
 41→}
 42→
 43→function RelativeTime({ timestamp }: { timestamp: number }) {
 44→  const [, setTick] = useState(0);
 45→
 46→  useEffect(() => {
 47→    const id = setInterval(() => setTick((t) => t + 1), 30_000);
 48→    return () => clearInterval(id);
 49→  }, []);
 50→
 51→  return (
 52→    <time
 53→      dateTime={new Date(timestamp).toISOString()}
 54→      title={formatAbsoluteTime(timestamp)}
 55→      className="text-[10px] text-muted-foreground/60"
 56→    >
 57→      {formatRelativeTime(timestamp)}
 58→    </time>
 59→  );
 60→}
 61→
 62→// ── Copy button ─────────────────────────────────────────────────────────
 63→
 64→function CopyButton({ text }: { text: string }) {
 65→  const [copied, setCopied] = useState(false);
 66→
 67→  function handleCopy() {
 68→    navigator.clipboard.writeText(text).then(() => {
 69→      setCopied(true);
 70→      setTimeout(() => setCopied(false), 1500);
 71→    });
 72→  }
 73→
 74→  return (
 75→    <button
 76→      onClick={handleCopy}
 77→      className="absolute top-1 right-1 rounded p-1 opacity-0 transition-opacity hover:bg-muted/50 group-hover:opacity-100"
 78→      aria-label="Copy message"
 79→    >
 80→      {copied ? (
 81→        <Check className="size-3 text-green-400" />
 82→      ) : (
 83→        <Copy className="size-3 text-muted-foreground" />
 84→      )}
 85→    </button>
 86→  );
 87→}
 88→
 89→// ── Message component ───────────────────────────────────────────────────
 90→
 91→export function Message({ message, onSendMessage }: { message: ChatMessage; onSendMessage?: (content: string) => void }) {
 92→  if (message.role === "system") {
 93→    return (
 94→      <div className="py-1 text-center text-xs italic text-muted-foreground">
 95→        {message.content}
 96→      </div>
 97→    );
